def _allow_redirect(redirect_url: str | None) -> bool:
    """Return True if redirect_url points to one of our own post-login pages."""

    if not redirect_url:
        return False

    # Reject absolute URLs, scheme-relative URLs ("//evil.com") and backslash tricks
    if "\\" in redirect_url or not redirect_url.startswith("/"):
        return False

    parsed = urlparse(redirect_url)
    if parsed.scheme or parsed.netloc:
        return False

    try:
        match = resolve(parsed.path)
    except Resolver404:
        return False

    return match.url_name in POST_LOGIN_ROUTES

